package main

import (
	"bufio"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

// ====== Type Definitions ======

type Pipeline struct {
	Name       string               `yaml:"name"`
	Version    string               `yaml:"version"`
	Parameters map[string]Parameter `yaml:"parameters"`
	Stages     []StageDef           `yaml:"stages"`
}

type Parameter struct {
	Type   string        `yaml:"type"`
	Values []interface{} `yaml:"values"`
}

type StageDef struct {
	Name      string            `yaml:"name"`
	Command   string            `yaml:"command"`
	DependsOn []string          `yaml:"depends_on"`
	Inputs    []IORef           `yaml:"inputs"`
	Outputs   []IORef           `yaml:"outputs"`
	Env       map[string]string `yaml:"env"`
	Metrics   []MetricDef       `yaml:"metrics"`
	Retry     *RetryConfig      `yaml:"retry"`
	Condition *Condition        `yaml:"condition"`
}

type IORef struct {
	Path string `yaml:"path"`
	Type string `yaml:"type"`
}

type MetricDef struct {
	Name      string `yaml:"name"`
	Objective string `yaml:"objective"`
}

type RetryConfig struct {
	MaxAttempts    int     `yaml:"max_attempts"`
	BackoffSeconds float64 `yaml:"backoff_seconds"`
}

type Condition struct {
	Metric    string  `yaml:"metric"`
	Operator  string  `yaml:"operator"`
	Threshold float64 `yaml:"threshold"`
}

type StageState struct {
	Name      string       `json:"name"`
	Status    string       `json:"status"`
	ExitCode  int          `json:"exit_code"`
	Metrics   []MetricData `json:"metrics"`
	StartTime string       `json:"start_time"`
	EndTime   string       `json:"end_time"`
	Retries   int          `json:"retries"`
}

type MetricData struct {
	Metric string  `json:"metric"`
	Value  float64 `json:"value"`
}

type ArtifactIndex struct {
	Entries []ArtifactEntry `json:"entries"`
}

type ArtifactEntry struct {
	ExperimentID string `json:"experiment_id"`
	StageName    string `json:"stage_name"`
	Path         string `json:"path"`
	Hash         string `json:"hash"`
	Size         int64  `json:"size"`
}

// ====== Pipeline Loading ======

func loadPipeline(path string) (*Pipeline, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var p Pipeline
	if err := yaml.Unmarshal(data, &p); err != nil {
		return nil, err
	}
	return &p, nil
}

// ====== Helpers ======

func formatValue(v interface{}) string {
	switch val := v.(type) {
	case float64:
		return strconv.FormatFloat(val, 'f', -1, 64)
	case int:
		return strconv.Itoa(val)
	case string:
		return val
	default:
		return fmt.Sprintf("%v", v)
	}
}

func sortedParamKeys(params map[string]Parameter) []string {
	keys := make([]string, 0, len(params))
	for k := range params {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func expandParameters(params map[string]Parameter) []map[string]interface{} {
	keys := sortedParamKeys(params)
	if len(keys) == 0 {
		return []map[string]interface{}{{}}
	}
	combos := []map[string]interface{}{{}}
	for _, key := range keys {
		param := params[key]
		if len(param.Values) == 0 {
			return nil
		}
		var newCombos []map[string]interface{}
		for _, combo := range combos {
			for _, val := range param.Values {
				newCombo := make(map[string]interface{})
				for k, v := range combo {
					newCombo[k] = v
				}
				newCombo[key] = val
				newCombos = append(newCombos, newCombo)
			}
		}
		combos = newCombos
	}
	return combos
}

func experimentID(combo map[string]interface{}) string {
	if len(combo) == 0 {
		return "exp_default"
	}
	keys := make([]string, 0, len(combo))
	for k := range combo {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, len(keys))
	for i, k := range keys {
		parts[i] = k + "=" + formatValue(combo[k])
	}
	return "exp_" + strings.Join(parts, "_")
}

func topoSort(stages []StageDef) ([][]string, error) {
	stageMap := make(map[string]*StageDef)
	for i := range stages {
		stageMap[stages[i].Name] = &stages[i]
	}
	inDegree := make(map[string]int)
	dependents := make(map[string][]string)
	for _, s := range stages {
		if _, ok := inDegree[s.Name]; !ok {
			inDegree[s.Name] = 0
		}
		for _, dep := range s.DependsOn {
			if _, exists := stageMap[dep]; exists {
				inDegree[s.Name]++
				dependents[dep] = append(dependents[dep], s.Name)
			}
		}
	}
	var groups [][]string
	processed := 0
	for processed < len(stages) {
		var group []string
		for name, deg := range inDegree {
			if deg == 0 {
				group = append(group, name)
			}
		}
		if len(group) == 0 {
			return groups, fmt.Errorf("circular dependency detected")
		}
		sort.Strings(group)
		groups = append(groups, group)
		for _, name := range group {
			delete(inDegree, name)
			processed++
			for _, dep := range dependents[name] {
				inDegree[dep]--
			}
		}
	}
	return groups, nil
}

func evalCondition(cond *Condition, metrics map[string]float64) bool {
	val, ok := metrics[cond.Metric]
	if !ok {
		return false
	}
	switch cond.Operator {
	case ">=":
		return val >= cond.Threshold
	case ">":
		return val > cond.Threshold
	case "<=":
		return val <= cond.Threshold
	case "<":
		return val < cond.Threshold
	case "==":
		return val == cond.Threshold
	case "!=":
		return val != cond.Threshold
	default:
		return false
	}
}

func substituteEnv(env map[string]string, combo map[string]interface{}) map[string]string {
	result := make(map[string]string)
	for k, v := range env {
		for pk, pv := range combo {
			placeholder := "${" + pk + "}"
			v = strings.ReplaceAll(v, placeholder, formatValue(pv))
		}
		result[k] = v
	}
	return result
}

func validatePipeline(p *Pipeline) []string {
	var errs []string
	seen := make(map[string]int)
	for _, s := range p.Stages {
		if s.Name == "" {
			errs = append(errs, "stage missing required field: name")
		} else {
			seen[s.Name]++
		}
	}
	for name, count := range seen {
		if count > 1 {
			errs = append(errs, fmt.Sprintf("duplicate stage name: %q", name))
		}
	}
	stageNames := make(map[string]bool)
	for _, s := range p.Stages {
		if s.Name != "" {
			stageNames[s.Name] = true
		}
	}
	for _, s := range p.Stages {
		if s.Command == "" && s.Name != "" {
			errs = append(errs, fmt.Sprintf("stage %q missing required field: command", s.Name))
		} else if s.Command == "" && s.Name == "" {
			errs = append(errs, "stage missing required field: command")
		}
	}
	for _, s := range p.Stages {
		for _, dep := range s.DependsOn {
			if !stageNames[dep] {
				errs = append(errs, fmt.Sprintf("stage %q references undefined stage: %q", s.Name, dep))
			}
		}
	}
	// Check cycles using Kahn's algorithm
	inDeg := make(map[string]int)
	deps := make(map[string][]string)
	for _, s := range p.Stages {
		if s.Name == "" {
			continue
		}
		if _, ok := inDeg[s.Name]; !ok {
			inDeg[s.Name] = 0
		}
		for _, dep := range s.DependsOn {
			if stageNames[dep] {
				inDeg[s.Name]++
				deps[dep] = append(deps[dep], s.Name)
			}
		}
	}
	remaining := make(map[string]int)
	for k, v := range inDeg {
		remaining[k] = v
	}
	processed := 0
	for processed < len(remaining) {
		found := false
		for name, deg := range remaining {
			if deg == 0 {
				delete(remaining, name)
				processed++
				found = true
				for _, d := range deps[name] {
					remaining[d]--
				}
			}
		}
		if !found {
			var cycleStages []string
			for name := range remaining {
				cycleStages = append(cycleStages, name)
			}
			sort.Strings(cycleStages)
			errs = append(errs, fmt.Sprintf("circular dependency detected among stages: %s", strings.Join(cycleStages, ", ")))
			break
		}
	}
	return errs
}

// ====== State Management ======

func stateDir(expID string) string {
	return filepath.Join(".mlpipe", "state", expID)
}

func stateFile(expID, stageName string) string {
	return filepath.Join(stateDir(expID), stageName+".json")
}

func loadState(expID, stageName string) (*StageState, error) {
	data, err := os.ReadFile(stateFile(expID, stageName))
	if err != nil {
		return nil, err
	}
	var st StageState
	if err := json.Unmarshal(data, &st); err != nil {
		return nil, err
	}
	return &st, nil
}

func saveState(expID string, st *StageState) error {
	dir := stateDir(expID)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(st, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, st.Name+".json"), data, 0644)
}

// ====== Artifact Management ======

func artifactBlobDir() string {
	return filepath.Join(".mlpipe", "artifacts", "blobs")
}

func artifactIndexPath() string {
	return filepath.Join(".mlpipe", "artifacts", "index.json")
}

func loadArtifactIndex() (*ArtifactIndex, error) {
	data, err := os.ReadFile(artifactIndexPath())
	if err != nil {
		if os.IsNotExist(err) {
			return &ArtifactIndex{Entries: []ArtifactEntry{}}, nil
		}
		return nil, err
	}
	var idx ArtifactIndex
	if err := json.Unmarshal(data, &idx); err != nil {
		return nil, err
	}
	if idx.Entries == nil {
		idx.Entries = []ArtifactEntry{}
	}
	return &idx, nil
}

func saveArtifactIndex(idx *ArtifactIndex) error {
	dir := filepath.Dir(artifactIndexPath())
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(idx, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(artifactIndexPath(), data, 0644)
}

func storeArtifact(expID, stageName, filePath string) error {
	f, err := os.Open(filePath)
	if err != nil {
		return err
	}
	defer f.Close()

	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return err
	}
	hash := hex.EncodeToString(h.Sum(nil))

	info, err := f.Stat()
	if err != nil {
		return err
	}

	blobDir := artifactBlobDir()
	if err := os.MkdirAll(blobDir, 0755); err != nil {
		return err
	}
	blobPath := filepath.Join(blobDir, hash)
	if _, err := os.Stat(blobPath); os.IsNotExist(err) {
		f.Seek(0, 0)
		dst, err := os.Create(blobPath)
		if err != nil {
			return err
		}
		defer dst.Close()
		if _, err := io.Copy(dst, f); err != nil {
			return err
		}
	}

	idx, err := loadArtifactIndex()
	if err != nil {
		return err
	}
	idx.Entries = append(idx.Entries, ArtifactEntry{
		ExperimentID: expID,
		StageName:    stageName,
		Path:         filePath,
		Hash:         hash,
		Size:         info.Size(),
	})
	return saveArtifactIndex(idx)
}

// ====== Stage Execution ======

func executeStage(stage *StageDef, combo map[string]interface{}) (int, []MetricData) {
	resolvedEnv := substituteEnv(stage.Env, combo)

	cmd := exec.Command("sh", "-c", stage.Command)
	cmd.Env = os.Environ()
	for k, v := range resolvedEnv {
		cmd.Env = append(cmd.Env, k+"="+v)
	}

	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return 1, nil
	}
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		return 1, nil
	}

	var metrics []MetricData
	scanner := bufio.NewScanner(stdout)
	for scanner.Scan() {
		line := scanner.Text()
		var m map[string]interface{}
		if json.Unmarshal([]byte(line), &m) == nil {
			if name, ok := m["metric"].(string); ok {
				if val, ok := m["value"].(float64); ok {
					metrics = append(metrics, MetricData{Metric: name, Value: val})
				}
			}
		}
	}

	exitCode := 0
	if err := cmd.Wait(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = 1
		}
	}
	return exitCode, metrics
}

func runStageWithRetry(stage *StageDef, combo map[string]interface{}) (int, []MetricData, int) {
	maxAttempts := 1
	backoff := 0.0
	if stage.Retry != nil {
		maxAttempts = stage.Retry.MaxAttempts
		backoff = stage.Retry.BackoffSeconds
	}

	var exitCode int
	var metrics []MetricData
	retries := 0

	for attempt := 0; attempt < maxAttempts; attempt++ {
		if attempt > 0 {
			retries = attempt
			delay := backoff * math.Pow(2, float64(attempt-1))
			if delay > 0 {
				time.Sleep(time.Duration(delay * float64(time.Second)))
			}
		}
		exitCode, metrics = executeStage(stage, combo)
		if exitCode == 0 {
			return exitCode, metrics, retries
		}
	}
	return exitCode, metrics, retries
}

// ====== Commands ======

func cmdValidate(pipelinePath string) {
	p, err := loadPipeline(pipelinePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading pipeline: %v\n", err)
		os.Exit(1)
	}
	errs := validatePipeline(p)
	if len(errs) == 0 {
		fmt.Println("pipeline is valid")
		os.Exit(0)
	}
	for _, e := range errs {
		fmt.Fprintf(os.Stderr, "error: %s\n", e)
	}
	os.Exit(1)
}

func cmdPlan(pipelinePath string) {
	p, err := loadPipeline(pipelinePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading pipeline: %v\n", err)
		os.Exit(1)
	}
	errs := validatePipeline(p)
	if len(errs) > 0 {
		for _, e := range errs {
			fmt.Fprintf(os.Stderr, "error: %s\n", e)
		}
		os.Exit(1)
	}

	groups, err := topoSort(p.Stages)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	combos := expandParameters(p.Parameters)

	result := map[string]interface{}{
		"stages_order":          groups,
		"total_experiments":     len(combos),
		"parameter_combinations": combos,
	}

	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	enc.Encode(result)
}

func cmdRun(pipelinePath string, args []string) {
	p, err := loadPipeline(pipelinePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading pipeline: %v\n", err)
		os.Exit(1)
	}
	errs := validatePipeline(p)
	if len(errs) > 0 {
		for _, e := range errs {
			fmt.Fprintf(os.Stderr, "error: %s\n", e)
		}
		os.Exit(1)
	}

	experimentIdx := -1
	resume := false
	for i := 0; i < len(args); i++ {
		if args[i] == "--experiment" && i+1 < len(args) {
			idx, err := strconv.Atoi(args[i+1])
			if err != nil {
				fmt.Fprintf(os.Stderr, "invalid experiment index: %s\n", args[i+1])
				os.Exit(1)
			}
			experimentIdx = idx
			i++
		} else if args[i] == "--resume" {
			resume = true
		}
	}

	groups, err := topoSort(p.Stages)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	combos := expandParameters(p.Parameters)
	if experimentIdx >= 0 {
		if experimentIdx >= len(combos) {
			fmt.Fprintf(os.Stderr, "experiment index %d out of range (0-%d)\n", experimentIdx, len(combos)-1)
			os.Exit(1)
		}
		combos = combos[experimentIdx : experimentIdx+1]
	}

	stageMap := make(map[string]*StageDef)
	for i := range p.Stages {
		stageMap[p.Stages[i].Name] = &p.Stages[i]
	}

	// Build dependents map for propagation
	dependentsOf := make(map[string][]string)
	for _, s := range p.Stages {
		for _, dep := range s.DependsOn {
			dependentsOf[dep] = append(dependentsOf[dep], s.Name)
		}
	}

	for _, combo := range combos {
		expID := experimentID(combo)
		fmt.Fprintf(os.Stderr, "=== Running experiment: %s ===\n", expID)

		metricContext := make(map[string]float64)
		stageStatuses := make(map[string]string)

		// Flat execution order from groups
		var execOrder []string
		for _, group := range groups {
			execOrder = append(execOrder, group...)
		}

		for _, stageName := range execOrder {
			stage := stageMap[stageName]

			// Check resume
			if resume {
				st, err := loadState(expID, stageName)
				if err == nil && st.Status == "completed" {
					fmt.Fprintf(os.Stderr, "  [%s] resumed (completed)\n", stageName)
					stageStatuses[stageName] = "completed"
					for _, m := range st.Metrics {
						metricContext[m.Metric] = m.Value
					}
					continue
				}
			}

			// Check dependencies
			depFailed := false
			for _, dep := range stage.DependsOn {
				status, ok := stageStatuses[dep]
				if !ok || (status != "completed") {
					depFailed = true
					break
				}
			}
			if depFailed {
				fmt.Fprintf(os.Stderr, "  [%s] skipped (dependency not met)\n", stageName)
				st := &StageState{
					Name:    stageName,
					Status:  "skipped",
					Metrics: []MetricData{},
				}
				stageStatuses[stageName] = "skipped"
				saveState(expID, st)
				continue
			}

			// Check condition
			if stage.Condition != nil {
				if !evalCondition(stage.Condition, metricContext) {
					fmt.Fprintf(os.Stderr, "  [%s] skipped (condition not met)\n", stageName)
					st := &StageState{
						Name:    stageName,
						Status:  "skipped",
						Metrics: []MetricData{},
					}
					stageStatuses[stageName] = "skipped"
					saveState(expID, st)
					continue
				}
			}

			// Execute stage
			fmt.Fprintf(os.Stderr, "  [%s] running...\n", stageName)
			startTime := time.Now().UTC().Format(time.RFC3339)

			exitCode, metrics, retries := runStageWithRetry(stage, combo)

			endTime := time.Now().UTC().Format(time.RFC3339)

			status := "completed"
			if exitCode != 0 {
				status = "failed"
			}

			if metrics == nil {
				metrics = []MetricData{}
			}

			st := &StageState{
				Name:      stageName,
				Status:    status,
				ExitCode:  exitCode,
				Metrics:   metrics,
				StartTime: startTime,
				EndTime:   endTime,
				Retries:   retries,
			}
			stageStatuses[stageName] = status
			saveState(expID, st)

			if status == "completed" {
				for _, m := range metrics {
					metricContext[m.Metric] = m.Value
				}
				// Store artifacts
				for _, out := range stage.Outputs {
					if out.Type == "file" {
						storeArtifact(expID, stageName, out.Path)
					}
				}
			}

			fmt.Fprintf(os.Stderr, "  [%s] %s (exit=%d, retries=%d)\n", stageName, status, exitCode, retries)
		}
	}
}

func cmdReport(pipelinePath string) {
	p, err := loadPipeline(pipelinePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading pipeline: %v\n", err)
		os.Exit(1)
	}

	// Collect metric objectives from pipeline definition
	objectives := make(map[string]string)
	for _, s := range p.Stages {
		for _, m := range s.Metrics {
			objectives[m.Name] = m.Objective
		}
	}

	// Scan state directories for experiments
	stateBase := filepath.Join(".mlpipe", "state")
	entries, _ := os.ReadDir(stateBase)

	type ExpResult struct {
		ID      string             `json:"id"`
		Metrics map[string]float64 `json:"metrics"`
	}

	var experiments []ExpResult
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		expID := entry.Name()
		expDir := filepath.Join(stateBase, expID)
		files, _ := os.ReadDir(expDir)
		metrics := make(map[string]float64)
		for _, f := range files {
			if !strings.HasSuffix(f.Name(), ".json") {
				continue
			}
			data, err := os.ReadFile(filepath.Join(expDir, f.Name()))
			if err != nil {
				continue
			}
			var st StageState
			if err := json.Unmarshal(data, &st); err != nil {
				continue
			}
			for _, m := range st.Metrics {
				metrics[m.Metric] = m.Value
			}
		}
		experiments = append(experiments, ExpResult{ID: expID, Metrics: metrics})
	}

	// Sort experiments by ID
	sort.Slice(experiments, func(i, j int) bool {
		return experiments[i].ID < experiments[j].ID
	})

	// Compute metric summary
	type MetricSummary struct {
		Mean float64 `json:"mean"`
		Std  float64 `json:"std"`
		Min  float64 `json:"min"`
		Max  float64 `json:"max"`
	}

	metricValues := make(map[string][]float64)
	for _, exp := range experiments {
		for name, val := range exp.Metrics {
			metricValues[name] = append(metricValues[name], val)
		}
	}

	metricSummary := make(map[string]MetricSummary)
	for name, vals := range metricValues {
		if len(vals) == 0 {
			continue
		}
		sum := 0.0
		minV := vals[0]
		maxV := vals[0]
		for _, v := range vals {
			sum += v
			if v < minV {
				minV = v
			}
			if v > maxV {
				maxV = v
			}
		}
		mean := sum / float64(len(vals))
		varSum := 0.0
		for _, v := range vals {
			d := v - mean
			varSum += d * d
		}
		std := math.Sqrt(varSum / float64(len(vals)))
		metricSummary[name] = MetricSummary{
			Mean: mean,
			Std:  std,
			Min:  minV,
			Max:  maxV,
		}
	}

	// Compute metric rankings
	type RankEntry struct {
		ID    string  `json:"id"`
		Value float64 `json:"value"`
		Rank  int     `json:"rank"`
	}

	metricRankings := make(map[string][]RankEntry)
	for metricName, obj := range objectives {
		if obj != "minimize" && obj != "maximize" {
			continue
		}
		type expVal struct {
			id  string
			val float64
		}
		var evs []expVal
		for _, exp := range experiments {
			if v, ok := exp.Metrics[metricName]; ok {
				evs = append(evs, expVal{exp.ID, v})
			}
		}
		if obj == "minimize" {
			sort.Slice(evs, func(i, j int) bool {
				if evs[i].val != evs[j].val {
					return evs[i].val < evs[j].val
				}
				return evs[i].id < evs[j].id
			})
		} else {
			sort.Slice(evs, func(i, j int) bool {
				if evs[i].val != evs[j].val {
					return evs[i].val > evs[j].val
				}
				return evs[i].id < evs[j].id
			})
		}
		ranks := make([]RankEntry, len(evs))
		for i, ev := range evs {
			ranks[i] = RankEntry{ID: ev.id, Value: ev.val, Rank: i + 1}
		}
		metricRankings[metricName] = ranks
	}

	// Find best experiment
	bestExpID := ""
	bestAvgRank := math.MaxFloat64

	if len(metricRankings) > 0 {
		// Compute average rank per experiment
		expRankSums := make(map[string]float64)
		expRankCounts := make(map[string]int)
		for _, ranks := range metricRankings {
			for _, r := range ranks {
				expRankSums[r.ID] += float64(r.Rank)
				expRankCounts[r.ID]++
			}
		}
		for id, sum := range expRankSums {
			count := expRankCounts[id]
			if count == 0 {
				continue
			}
			avgRank := sum / float64(count)
			if avgRank < bestAvgRank || (avgRank == bestAvgRank && id < bestExpID) {
				bestAvgRank = avgRank
				bestExpID = id
			}
		}
	}

	// Build output - filter out 'report' objective metrics from rankings
	// but keep them in experiment metrics
	experimentsOut := make([]map[string]interface{}, len(experiments))
	for i, exp := range experiments {
		experimentsOut[i] = map[string]interface{}{
			"id":      exp.ID,
			"metrics": exp.Metrics,
		}
	}

	result := map[string]interface{}{
		"experiments":      experimentsOut,
		"metric_summary":   metricSummary,
		"metric_rankings":  metricRankings,
		"best_experiment":  bestExpID,
	}

	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	enc.Encode(result)
}

func cmdArtifacts(pipelinePath string, args []string) {
	listFlag := false
	gcFlag := false
	for _, a := range args {
		if a == "--list" {
			listFlag = true
		}
		if a == "--gc" {
			gcFlag = true
		}
	}

	if listFlag {
		idx, err := loadArtifactIndex()
		if err != nil {
			fmt.Fprintf(os.Stderr, "error loading artifact index: %v\n", err)
			os.Exit(1)
		}
		enc := json.NewEncoder(os.Stdout)
		enc.SetIndent("", "  ")
		enc.Encode(idx)
		return
	}

	if gcFlag {
		idx, err := loadArtifactIndex()
		if err != nil {
			fmt.Fprintf(os.Stderr, "error loading artifact index: %v\n", err)
			os.Exit(1)
		}

		// Find completed experiments
		stateBase := filepath.Join(".mlpipe", "state")
		entries, _ := os.ReadDir(stateBase)
		completedExps := make(map[string]bool)

		for _, entry := range entries {
			if !entry.IsDir() {
				continue
			}
			expDir := filepath.Join(stateBase, entry.Name())
			files, _ := os.ReadDir(expDir)
			allDone := true
			hasStages := false
			for _, f := range files {
				if !strings.HasSuffix(f.Name(), ".json") {
					continue
				}
				hasStages = true
				data, err := os.ReadFile(filepath.Join(expDir, f.Name()))
				if err != nil {
					allDone = false
					break
				}
				var st StageState
				if err := json.Unmarshal(data, &st); err != nil {
					allDone = false
					break
				}
				if st.Status != "completed" && st.Status != "skipped" {
					allDone = false
					break
				}
			}
			if hasStages && allDone {
				completedExps[entry.Name()] = true
			}
		}

		// Find referenced hashes from completed experiments
		referencedHashes := make(map[string]bool)
		for _, e := range idx.Entries {
			if completedExps[e.ExperimentID] {
				referencedHashes[e.Hash] = true
			}
		}

		// Scan blobs directory
		blobDir := artifactBlobDir()
		blobEntries, _ := os.ReadDir(blobDir)
		reclaimedBytes := int64(0)
		remainingBlobs := 0

		for _, be := range blobEntries {
			blobPath := filepath.Join(blobDir, be.Name())
			if referencedHashes[be.Name()] {
				remainingBlobs++
			} else {
				info, err := be.Info()
				if err == nil {
					reclaimedBytes += info.Size()
				}
				os.Remove(blobPath)
			}
		}

		// Clean up index entries for removed blobs
		var newEntries []ArtifactEntry
		for _, e := range idx.Entries {
			if referencedHashes[e.Hash] {
				newEntries = append(newEntries, e)
			}
		}
		if newEntries == nil {
			newEntries = []ArtifactEntry{}
		}
		idx.Entries = newEntries
		saveArtifactIndex(idx)

		result := map[string]interface{}{
			"reclaimed_bytes": reclaimedBytes,
			"remaining_blobs": remainingBlobs,
		}
		enc := json.NewEncoder(os.Stdout)
		enc.SetIndent("", "  ")
		enc.Encode(result)
		return
	}

	// Default: print usage
	fmt.Fprintln(os.Stderr, "Usage: mlpipe artifacts <pipeline.yaml> [--list] [--gc]")
}

// ====== Main ======

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "Usage: mlpipe <command> [args...]")
		fmt.Fprintln(os.Stderr, "Commands: validate, plan, run, report, artifacts")
		os.Exit(1)
	}

	cmd := os.Args[1]

	switch cmd {
	case "validate":
		if len(os.Args) < 3 {
			fmt.Fprintln(os.Stderr, "Usage: mlpipe validate <pipeline.yaml>")
			os.Exit(1)
		}
		cmdValidate(os.Args[2])
	case "plan":
		if len(os.Args) < 3 {
			fmt.Fprintln(os.Stderr, "Usage: mlpipe plan <pipeline.yaml>")
			os.Exit(1)
		}
		cmdPlan(os.Args[2])
	case "run":
		if len(os.Args) < 3 {
			fmt.Fprintln(os.Stderr, "Usage: mlpipe run <pipeline.yaml> [--experiment <index>] [--resume]")
			os.Exit(1)
		}
		cmdRun(os.Args[2], os.Args[3:])
	case "report":
		if len(os.Args) < 3 {
			fmt.Fprintln(os.Stderr, "Usage: mlpipe report <pipeline.yaml>")
			os.Exit(1)
		}
		cmdReport(os.Args[2])
	case "artifacts":
		if len(os.Args) < 3 {
			fmt.Fprintln(os.Stderr, "Usage: mlpipe artifacts <pipeline.yaml> [--list] [--gc]")
			os.Exit(1)
		}
		cmdArtifacts(os.Args[2], os.Args[3:])
	default:
		fmt.Fprintf(os.Stderr, "error: unknown command %q\n", cmd)
		os.Exit(1)
	}
}
