\t\t\treturn &ArtifactIndex{Entries: []ArtifactEntry{}}, nil
\t\t}
\t\treturn nil, err
\t}
\tvar idx ArtifactIndex
\tif err := json.Unmarshal(data, &idx); err != nil {
\t\treturn nil, err
\t}
\tif idx.Entries == nil {
\t\tidx.Entries = []ArtifactEntry{}
\t}
\treturn &idx, nil
}

func saveArtifactIndex(idx *ArtifactIndex) error {
\tdir := filepath.Dir(artifactIndexPath())
\tif err := os.MkdirAll(dir, 0755); err != nil {
\t\treturn err
\t}
\tdata, err := json.MarshalIndent(idx, \"\", \"  \")
\tif err != nil {
\t\treturn err
\t}
\treturn os.WriteFile(artifactIndexPath(), data, 0644)
}

func storeArtifact(expID, stageName, filePath string) error {
\tf, err := os.Open(filePath)
\tif err != nil {
\t\treturn err
\t}
\tdefer f.Close()
\th := sha256.New()
\tif _, err := io.Copy(h, f); err != nil {
\t\treturn err
\t}
\thash := hex.EncodeToString(h.Sum(nil))
\tinfo, err := f.Stat()
\tif err != nil {
\t\treturn err
\t}
\tblobDir := artifactBlobDir()
\tif err := os.MkdirAll(blobDir, 0755); err != nil {
\t\treturn err
\t}
\tblobPath := filepath.Join(blobDir, hash)
\tif _, err := os.Stat(blobPath); os.IsNotExist(err) {
\t\tf.Seek(0, 0)
\t\tdst, err := os.Create(blobPath)
\t\tif err != nil {
\t\t\treturn err
\t\t}
\t\tdefer dst.Close()
\t\tif _, err := io.Copy(dst, f); err != nil {
\t\t\treturn err
\t\t}
\t}
\tidx, err := loadArtifactIndex()
\tif err != nil {
\t\treturn err
\t}
\tidx.Entries = append(idx.Entries, ArtifactEntry{
\t\tExperimentID: expID,
\t\tStageName:    stageName,
\t\tPath:         filePath,
\t\tHash:         hash,
\t\tSize:         info.Size(),
\t})
\treturn saveArtifactIndex(idx)
}

func executeStage(stage *StageDef, combo map[string]interface{}) (int, []MetricData) {
\tresolvedEnv := substituteEnv(stage.Env, combo)
\tcmd := exec.Command(\"sh\", \"-c\", stage.Command)
\tcmd.Env = os.Environ()
\tfor k, v := range resolvedEnv {
\t\tcmd.Env = append(cmd.Env, k+\"=\"+v)
\t}
\tstdout, err := cmd.StdoutPipe()
\tif err != nil {
\t\treturn 1, nil
\t}
\tcmd.Stderr = os.Stderr
\tif err := cmd.Start(); err != nil {
\t\treturn 1, nil
\t}
\tvar metrics []MetricData
\tscanner := bufio.NewScanner(stdout)
\tfor scanner.Scan() {
\t\tline := scanner.Text()
\t\tvar m map[string]interface{}
\t\tif json.Unmarshal([]byte(line), &m) == nil {
\t\t\tif name, ok := m[\"metric\"].(string); ok {
\t\t\t\tif val, ok := m[\"value\"].(float64); ok {
\t\t\t\t\tmetrics = append(metrics, MetricData{Metric: name, Value: val})
\t\t\t\t}
\t\t\t}
\t\t}
\t}
\texitCode := 0
\tif err := cmd.Wait(); err != nil {
\t\tif exitErr, ok := err.(*exec.ExitError); ok {
\t\t\texitCode = exitErr.ExitCode()
\t\t} else {
\t\t\texitCode = 1
\t\t}
\t}
\treturn exitCode, metrics
}

func runStageWithRetry(stage *StageDef, combo map[string]interface{}) (int, []MetricData, int) {
\tmaxAttempts := 1
\tbackoff := 0.0
\tif stage.Retry != nil {
\t\tmaxAttempts = stage.Retry.MaxAttempts
\t\tbackoff = stage.Retry.BackoffSeconds
\t}
\tvar exitCode int
\tvar metrics []MetricData
\tretries := 0
\tfor attempt := 0; attempt < maxAttempts; attempt++ {
\t\tif attempt > 0 {
\t\t\tretries = attempt
\t\t\tdelay := backoff * math.Pow(2, float64(attempt-1))
\t\t\tif delay > 0 {
\t\t\t\ttime.Sleep(time.Duration(delay * float64(time.Second)))
\t\t\t}
\t\t}
\t\texitCode, metrics = executeStage(stage, combo)
\t\tif exitCode == 0 {
\t\t\treturn exitCode, metrics, retries
\t\t}
\t}
\treturn exitCode, metrics, retries
}

