func cmdRun(pipelinePath string, args []string) {
\tp, err := loadPipeline(pipelinePath)
\tif err != nil {
\t\tfmt.Fprintf(os.Stderr, \"error loading pipeline: %v\\n\", err)
\t\tos.Exit(1)
\t}
\terrs := validatePipeline(p)
\tif len(errs) > 0 {
\t\tfor _, e := range errs {
\t\t\tfmt.Fprintf(os.Stderr, \"error: %s\\n\", e)
\t\t}
\t\tos.Exit(1)
\t}
\texperimentIdx := -1
\tresume := false
\tfor i := 0; i < len(args); i++ {
\t\tif args[i] == \"--experiment\" && i+1 < len(args) {
\t\t\tidx, err := strconv.Atoi(args[i+1])
\t\t\tif err != nil {
\t\t\t\tfmt.Fprintf(os.Stderr, \"invalid experiment index: %s\\n\", args[i+1])
\t\t\t\tos.Exit(1)
\t\t\t}
\t\t\texperimentIdx = idx
\t\t\ti++
\t\t} else if args[i] == \"--resume\" {
\t\t\tresume = true
\t\t}
\t}
\tgroups, err := topoSort(p.Stages)
\tif err != nil {
\t\tfmt.Fprintf(os.Stderr, \"error: %v\\n\", err)
\t\tos.Exit(1)
\t}
\tcombos := expandParameters(p.Parameters)
\tif experimentIdx >= 0 {
\t\tif experimentIdx >= len(combos) {
\t\t\tfmt.Fprintf(os.Stderr, \"experiment index %d out of range (0-%d)\\n\", experimentIdx, len(combos)-1)
\t\t\tos.Exit(1)
\t\t}
\t\tcombos = combos[experimentIdx : experimentIdx+1]
\t}
\tstageMap := make(map[string]*StageDef)
\tfor i := range p.Stages {
\t\tstageMap[p.Stages[i].Name] = &p.Stages[i]
\t}
\tfor _, combo := range combos {
\t\texpID := experimentID(combo)
\t\tfmt.Fprintf(os.Stderr, \"=== Running experiment: %s ===\\n\", expID)
\t\tmetricContext := make(map[string]float64)
\t\tstageStatuses := make(map[string]string)
\t\tvar execOrder []string
\t\tfor _, group := range groups {
\t\t\texecOrder = append(execOrder, group...)
\t\t}
\t\tfor _, stageName := range execOrder {
\t\t\tstage := stageMap[stageName]
\t\t\tif resume {
\t\t\t\tst, err := loadState(expID, stageName)
\t\t\t\tif err == nil && st.Status == \"completed\" {
\t\t\t\t\tfmt.Fprintf(os.Stderr, \"  [%s] resumed (completed)\\n\", stageName)
\t\t\t\t\tstageStatuses[stageName] = \"completed\"
\t\t\t\t\tfor _, m := range st.Metrics {
\t\t\t\t\t\tmetricContext[m.Metric] = m.Value
\t\t\t\t\t}
\t\t\t\t\tcontinue
\t\t\t\t}
\t\t\t}
\t\t\tdepFailed := false
\t\t\tfor _, dep := range stage.DependsOn {
\t\t\t\tstatus, ok := stageStatuses[dep]
\t\t\t\tif !ok || (status != \"completed\") {
\t\t\t\t\tdepFailed = true
\t\t\t\t\tbreak
\t\t\t\t}
\t\t\t}
\t\t\tif depFailed {
\t\t\t\tfmt.Fprintf(os.Stderr, \"  [%s] skipped (dependency not met)\\n\", stageName)
\t\t\t\tst := &StageState{
\t\t\t\t\tName:    stageName,
\t\t\t\t\tStatus:  \"skipped\",
\t\t\t\t\tMetrics: []MetricData{},
\t\t\t\t}
\t\t\t\tstageStatuses[stageName] = \"skipped\"
\t\t\t\tsaveState(expID, st)
\t\t\t\tcontinue
\t\t\t}
\t\t\tif stage.Condition != nil {
\t\t\t\tif !evalCondition(stage.Condition, metricContext) {
\t\t\t\t\tfmt.Fprintf(os.Stderr, \"  [%s] skipped (condition not met)\\n\", stageName)
\t\t\t\t\tst := &StageState{
\t\t\t\t\t\tName:    stageName,
\t\t\t\t\t\tStatus:  \"skipped\",
\t\t\t\t\t\tMetrics: []MetricData{},
\t\t\t\t\t}
\t\t\t\t\tstageStatuses[stageName] = \"skipped\"
\t\t\t\t\tsaveState(expID, st)
\t\t\t\t\tcontinue
\t\t\t\t}
\t\t\t}
\t\t\tfmt.Fprintf(os.Stderr, \"  [%s] running...\\n\", stageName)
\t\t\tstartTime := time.Now().UTC().Format(time.RFC3339)
\t\t\texitCode, metrics, retries := runStageWithRetry(stage, combo)
\t\t\tendTime := time.Now().UTC().Format(time.RFC3339)
\t\t\tstatus := \"completed\"
\t\t\tif exitCode != 0 {
\t\t\t\tstatus = \"failed\"
\t\t\t}
\t\t\tif metrics == nil {
\t\t\t\tmetrics = []MetricData{}
\t\t\t}
\t\t\tst := &StageState{
\t\t\t\tName:      stageName,
\t\t\t\tStatus:    status,
\t\t\t\tExitCode:  exitCode,
\t\t\t\tMetrics:   metrics,
\t\t\t\tStartTime: startTime,
\t\t\t\tEndTime:   endTime,
\t\t\t\tRetries:   retries,
\t\t\t}
\t\t\tstageStatuses[stageName] = status
\t\t\tsaveState(expID, st)
\t\t\tif status == \"completed\" {
\t\t\t\tfor _, m := range metrics {
\t\t\t\t\tmetricContext[m.Metric] = m.Value
\t\t\t\t}
\t\t\t\tfor _, out := range stage.Outputs {
\t\t\t\t\tif out.Type == \"file\" {
\t\t\t\t\t\tstoreArtifact(expID, stageName, out.Path)
\t\t\t\t\t}
\t\t\t\t}
\t\t\t}
\t\t\tfmt.Fprintf(os.Stderr, \"  [%s] %s (exit=%d, retries=%d)\\n\", stageName, status, exitCode, retries)
\t\t}
\t}
}

func cmdReport(pipelinePath string) {
\tp, err := loadPipeline(pipelinePath)
\tif err != nil {
\t\tfmt.Fprintf(os.Stderr, \"error loading pipeline: %v\\n\", err)
\t\tos.Exit(1)
\t}
\tobjectives := make(map[string]string)
\tfor _, s := range p.Stages {
\t\tfor _, m := range s.Metrics {
\t\t\tobjectives[m.Name] = m.Objective
\t\t}
\t}
\tstateBase := filepath.Join(\".mlpipe\", \"state\")
\tentries, _ := os.ReadDir(stateBase)
\ttype ExpResult struct {
\t\tID      string
\t\tMetrics map[string]float64
\t}
\tvar experiments []ExpResult
\tfor _, entry := range entries {
\t\tif !entry.IsDir() {
\t\t\tcontinue
\t\t}
\t\texpID := entry.Name()
\t\texpDir := filepath.Join(stateBase, expID)
\t\tfiles, _ := os.ReadDir(expDir)
\t\tmetrics := make(map[string]float64)
\t\tfor _, f := range files {
\t\t\tif !strings.HasSuffix(f.Name(), \".json\") {
\t\t\t\tcontinue
\t\t\t}
\t\t\tdata, err := os.ReadFile(filepath.Join(expDir, f.Name()))
\t\t\tif err != nil {
\t\t\t\tcontinue
\t\t\t}
\t\t\tvar st StageState
\t\t\tif err := json.Unmarshal(data, &st); err != nil {
\t\t\t\tcontinue
\t\t\t}
\t\t\tfor _, m := range st.Metrics {
\t\t\t\tmetrics[m.Metric] = m.Value
\t\t\t}
\t\t}
\t\texperiments = append(experiments, ExpResult{ID: expID, Metrics: metrics})
\t}
\tsort.Slice(experiments, func(i, j int) bool {
\t\treturn experiments[i].ID < experiments[j].ID
\t})
\ttype MetricSummary struct {
\t\tMean float64 `json:\"mean\"`
\t\tStd  float64 `json:\"std\"`
\t\tMin  float64 `json:\"min\"`
\t\tMax  float64 `json:\"max\"`
\t}
\tmetricValues := make(map[string][]float64)
\tfor _, exp := range experiments {
\t\tfor name, val := range exp.Metrics {
\t\t\tmetricValues[name] = append(metricValues[name], val)
\t\t}
\t}
\tmetricSummary := make(map[string]MetricSummary)
\tfor name, vals := range metricValues {
\t\tif len(vals) == 0 {
\t\t\tcontinue
\t\t}
\t\tsum := 0.0
\t\tminV := vals[0]
\t\tmaxV := vals[0]
\t\tfor _, v := range vals {
\t\t\tsum += v
\t\t\tif v < minV {
\t\t\t\tminV = v
\t\t\t}
\t\t\tif v > maxV {
\t\t\t\tmaxV = v
\t\t\t}
\t\t}
\t\tmean := sum / float64(len(vals))
\t\tvarSum := 0.0
\t\tfor _, v := range vals {
\t\t\td := v - mean
\t\t\tvarSum += d * d
\t\t}
\t\tstd := math.Sqrt(varSum / float64(len(vals)))
\t\tmetricSummary[name] = MetricSummary{Mean: mean, Std: std, Min: minV, Max: maxV}
\t}
\ttype RankEntry struct {
\t\tID    string  `json:\"id\"`
\t\tValue float64 `json:\"value\"`
\t\tRank  int     `json:\"rank\"`
\t}
\tmetricRankings := make(map[string][]RankEntry)
\tfor metricName, obj := range objectives {
\t\tif obj != \"minimize\" && obj != \"maximize\" {
\t\t\tcontinue
\t\t}
\t\ttype expVal struct {
\t\t\tid  string
\t\t\tval float64
\t\t}
\t\tvar evs []expVal
\t\tfor _, exp := range experiments {
\t\t\tif v, ok := exp.Metrics[metricName]; ok {
\t\t\t\tevs = append(evs, expVal{exp.ID, v})
\t\t\t}
\t\t}
\t\tif obj == \"minimize\" {
\t\t\tsort.Slice(evs, func(i, j int) bool {
\t\t\t\tif evs[i].val != evs[j].val {
\t\t\t\t\treturn evs[i].val < evs[j].val
\t\t\t\t}
\t\t\t\treturn evs[i].id < evs[j].id
\t\t\t})
\t\t} else {
\t\t\tsort.Slice(evs, func(i, j int) bool {
\t\t\t\tif evs[i].val != evs[j].val {
\t\t\t\t\treturn evs[i].val > evs[j].val
\t\t\t\t}
\t\t\t\treturn evs[i].id < evs[j].id
\t\t\t})
\t\t}
\t\tranks := make([]RankEntry, len(evs))
\t\tfor i, ev := range evs {
\t\t\tranks[i] = RankEntry{ID: ev.id, Value: ev.val, Rank: i + 1}
\t\t}
\t\tmetricRankings[metricName] = ranks
\t}
\tbestExpID := \"\"
\tbestAvgRank := math.MaxFloat64
\tif len(metricRankings) > 0 {
\t\texpRankSums := make(map[string]float64)
\t\texpRankCounts := make(map[string]int)
\t\tfor _, ranks := range metricRankings {
\t\t\tfor _, r := range ranks {
\t\t\t\texpRankSums[r.ID] += float64(r.Rank)
\t\t\t\texpRankCounts[r.ID]++
\t\t\t}
\t\t}
\t\tfor id, sum := range expRankSums {
\t\t\tcount := expRankCounts[id]
\t\t\tif count == 0 {
\t\t\t\tcontinue
\t\t\t}
\t\t\tavgRank := sum / float64(count)
\t\t\tif avgRank < bestAvgRank || (avgRank == bestAvgRank && id < bestExpID) {
\t\t\t\tbestAvgRank = avgRank
\t\t\t\tbestExpID = id
\t\t\t}
\t\t}
\t}
\texperimentsOut := make([]map[string]interface{}, len(experiments))
\tfor i, exp := range experiments {
\t\texperimentsOut[i] = map[string]interface{}{
\t\t\t\"id\":      exp.ID,
\t\t\t\"metrics\": exp.Metrics,
\t\t}
\t}
\tresult := map[string]interface{}{
\t\t\"experiments\":     experimentsOut,
\t\t\"metric_summary\":  metricSummary,
\t\t\"metric_rankings\": metricRankings,
\t\t\"best_experiment\": bestExpID,
\t}
\tenc := json.NewEncoder(os.Stdout)
\tenc.SetIndent(\"\", \"  \")
\tenc.Encode(result)
}

func cmdArtifacts(pipelinePath string, args []string) {
\tlistFlag := false
\tgcFlag := false
\tfor _, a := range args {
\t\tif a == \"--list\" {
\t\t\tlistFlag = true
\t\t}
\t\tif a == \"--gc\" {
\t\t\tgcFlag = true
\t\t}
\t}
\tif listFlag {
\t\tidx, err := loadArtifactIndex()
\t\tif err != nil {
\t\t\tfmt.Fprintf(os.Stderr, \"error loading artifact index: %v\\n\", err)
\t\t\tos.Exit(1)
\t\t}
\t\tenc := json.NewEncoder(os.Stdout)
\t\tenc.SetIndent(\"\", \"  \")
\t\tenc.Encode(idx)
\t\treturn
\t}
\tif gcFlag {
\t\tidx, err := loadArtifactIndex()
\t\tif err != nil {
\t\t\tfmt.Fprintf(os.Stderr, \"error loading artifact index: %v\\n\", err)
\t\t\tos.Exit(1)
\t\t}
\t\tstateBase := filepath.Join(\".mlpipe\", \"state\")
\t\tentries, _ := os.ReadDir(stateBase)
\t\tcompletedExps := make(map[string]bool)
\t\tfor _, entry := range entries {
\t\t\tif !entry.IsDir() {
\t\t\t\tcontinue
\t\t\t}
\t\t\texpDir := filepath.Join(stateBase, entry.Name())
\t\t\tfiles, _ := os.ReadDir(expDir)
\t\t\tallDone := true
\t\t\thasStages := false
\t\t\tfor _, f := range files {
\t\t\t\tif !strings.HasSuffix(f.Name(), \".json\") {
\t\t\t\t\tcontinue
\t\t\t\t}
\t\t\t\thasStages = true
\t\t\t\tdata, err := os.ReadFile(filepath.Join(expDir, f.Name()))
\t\t\t\tif err != nil {
\t\t\t\t\tallDone = false
\t\t\t\t\tbreak
\t\t\t\t}
\t\t\t\tvar st StageState
\t\t\t\tif err := json.Unmarshal(data, &st); err != nil {
\t\t\t\t\tallDone = false
\t\t\t\t\tbreak
\t\t\t\t}
\t\t\t\tif st.Status != \"completed\" && st.Status != \"skipped\" {
\t\t\t\t\tallDone = false
\t\t\t\t\tbreak
\t\t\t\t}
\t\t\t}
\t\t\tif hasStages && allDone {
\t\t\t\tcompletedExps[entry.Name()] = true
\t\t\t}
\t\t}
\t\treferencedHashes := make(map[string]bool)
\t\tfor _, e := range idx.Entries {
\t\t\tif completedExps[e.ExperimentID] {
\t\t\t\treferencedHashes[e.Hash] = true
\t\t\t}
\t\t}
\t\tblobDir := artifactBlobDir()
\t\tblobEntries, _ := os.ReadDir(blobDir)
\t\treclaimedBytes := int64(0)
\t\tremainingBlobs := 0
\t\tfor _, be := range blobEntries {
\t\t\tblobPath := filepath.Join(blobDir, be.Name())
\t\t\tif referencedHashes[be.Name()] {
\t\t\t\tremainingBlobs++
\t\t\t} else {
\t\t\t\tinfo, err := be.Info()
\t\t\t\tif err == nil {
\t\t\t\t\treclaimedBytes += info.Size()
\t\t\t\t}
\t\t\t\tos.Remove(blobPath)
\t\t\t}
\t\t}
\t\tvar newEntries []ArtifactEntry
\t\tfor _, e := range idx.Entries {
\t\t\tif referencedHashes[e.Hash] {
\t\t\t\tnewEntries = append(newEntries, e)
\t\t\t}
\t\t}
\t\tif newEntries == nil {
\t\t\tnewEntries = []ArtifactEntry{}
\t\t}
\t\tidx.Entries = newEntries
\t\tsaveArtifactIndex(idx)
\t\tresult := map[string]interface{}{
\t\t\t\"reclaimed_bytes\": reclaimedBytes,
\t\t\t\"remaining_blobs\": remainingBlobs,
\t\t}
\t\tenc := json.NewEncoder(os.Stdout)
\t\tenc.SetIndent(\"\", \"  \")
\t\tenc.Encode(result)
\t\treturn
\t}
\tfmt.Fprintln(os.Stderr, \"Usage: mlpipe artifacts <pipeline.yaml> [--list] [--gc]\")
}

