func formatValue(v interface{}) string {
	switch val := v.(type) {
	case float64:
		return strconv.FormatFloat(val, 'f', -1, 64)
	case int:
		return strconv.Itoa(val)
	case string:
		return val
	default:
		return fmt.Sprintf("%v", val)
	}
}

func sortedParamKeys(params map[string]Parameter) []string {
	keys := make([]string, 0, len(params))
	for k := range params {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func expandParameters(params map[string]Parameter) []map[string]interface{} {
	keys := sortedParamKeys(params)
	if len(keys) == 0 {
		return []map[string]interface{}{{}}
	}
	combos := []map[string]interface{}{{}}
	for _, key := range keys {
		param := params[key]
		if len(param.Values) == 0 {
			return nil
		}
		var newCombos []map[string]interface{}
		for _, combo := range combos {
			for _, val := range param.Values {
				newCombo := make(map[string]interface{})
				for k, v := range combo {
					newCombo[k] = v
				}
				newCombo[key] = val
				newCombos = append(newCombos, newCombo)
			}
		}
		combos = newCombos
	}
	return combos
}

func experimentID(combo map[string]interface{}) string {
	if len(combo) == 0 {
		return "exp_default"
	}
	keys := make([]string, 0, len(combo))
	for k := range combo {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, len(keys))
	for i, k := range keys {
		parts[i] = k + "=" + formatValue(combo[k])
	}
	return "exp_" + strings.Join(parts, "_")
}

func topoSort(stages []StageDef) ([][]string, error) {
	stageMap := make(map[string]*StageDef)
	for i := range stages {
		stageMap[stages[i].Name] = &stages[i]
	}
	inDegree := make(map[string]int)
	dependents := make(map[string][]string)
	for _, s := range stages {
		if _, ok := inDegree[s.Name]; !ok {
			inDegree[s.Name] = 0
		}
		for _, dep := range s.DependsOn {
			if _, exists := stageMap[dep]; exists {
				inDegree[s.Name]++
				dependents[dep] = append(dependents[dep], s.Name)
			}
		}
	}
	var groups [][]string
	processed := 0
	for processed < len(stages) {
		var group []string
		for name, deg := range inDegree {
			if deg == 0 {
				group = append(group, name)
			}
		}
		if len(group) == 0 {
			return groups, fmt.Errorf("circular dependency detected")
		}
		sort.Strings(group)
		groups = append(groups, group)
		for _, name := range group {
			delete(inDegree, name)
			processed++
			for _, dep := range dependents[name] {
				inDegree[dep]--
			}
		}
	}
	return groups, nil
}

func evalCondition(cond *Condition, metrics map[string]float64) bool {
	val, ok := metrics[cond.Metric]
	if !ok {
		return false
	}
	switch cond.Operator {
	case ">=":
		return val >= cond.Threshold
	case ">":
		return val > cond.Threshold
	case "<=":
		return val <= cond.Threshold
	case "<":
		return val < cond.Threshold
	case "==":
		return val == cond.Threshold
	case "!=":
		return val != cond.Threshold
	default:
		return false
	}
}

func substituteEnv(env map[string]string, combo map[string]interface{}) map[string]string {
	result := make(map[string]string)
	for k, v := range env {
		for pk, pv := range combo {
			placeholder := "${" + pk + "}"
			v = strings.ReplaceAll(v, placeholder, formatValue(pv))
		}
		result[k] = v
	}
	return result
}

func validatePipeline(p *Pipeline) []string {
	var errs []string
	seen := make(map[string]int)
	for _, s := range p.Stages {
		if s.Name == "" {
			errs = append(errs, "stage missing required field: name")
		} else {
			seen[s.Name]++
		}
	}
	for name, count := range seen {
		if count > 1 {
			errs = append(errs, fmt.Sprintf("duplicate stage name: %q", name))
		}
	}
	stageNames := make(map[string]bool)
	for _, s := range p.Stages {
		if s.Name != "" {
			stageNames[s.Name] = true
		}
	}
	for _, s := range p.Stages {
		if s.Command == "" && s.Name != "" {
			errs = append(errs, fmt.Sprintf("stage %q missing required field: command", s.Name))
		} else if s.Command == "" && s.Name == "" {
			errs = append(errs, "stage missing required field: command")
		}
	}
	for _, s := range p.Stages {
		for _, dep := range s.DependsOn {
			if !stageNames[dep] {
				errs = append(errs, fmt.Sprintf("stage %q references undefined stage: %q", s.Name, dep))
			}
		}
	}
	inDeg := make(map[string]int)
	deps := make(map[string][]string)
	for _, s := range p.Stages {
		if s.Name == "" {
			continue
		}
		if _, ok := inDeg[s.Name]; !ok {
			inDeg[s.Name] = 0
		}
		for _, dep := range s.DependsOn {
			if stageNames[dep] {
				inDeg[s.Name]++
				deps[dep] = append(deps[dep], s.Name)
			}
		}
	}
	remaining := make(map[string]int)
	for k, v := range inDeg {
		remaining[k] = v
	}
	processed := 0
	for processed < len(remaining) {
		found := false
		for name, deg := range remaining {
			if deg == 0 {
				delete(remaining, name)
				processed++
				found = true
				for _, d := range deps[name] {
					remaining[d]--
				}
			}
		}
		if !found {
			var cycleStages []string
			for name := range remaining {
				cycleStages = append(cycleStages, name)
			}
			sort.Strings(cycleStages)
			errs = append(errs, fmt.Sprintf("circular dependency detected among stages: %s", strings.Join(cycleStages, ", ")))
			break
		}
	}
	return errs
}

func stateDir(expID string) string {
